+func TestAuthorityRecoveryUIDFlightLeaderCancellationKeepsFollowerRetryable(t *testing.T) {
+	d := authority.NewDirectory(authority.DirectoryOptions{RequireRecovery: true})
+	target := flightTarget(0)
